    },
    {
      "indicator": "MM20",
      "reading": "8.9865",
      "interpretation": "Suporte imediato (BB_mid). Preço acima indica tendência de curto prazo favorável."
    },
    {
      "indicator": "MM50",
      "reading": "8.5772",
      "interpretation": "Preço acima da MM50 reforça alta de médio prazo, mas MM50 ainda está abaixo da MM200."
    },
    {
      "indicator": "MM200",
      "reading": "8.7110",
      "interpretation": "Preço acima da MM200 sugere viés de longo prazo positivo, porém sem cruzamento MM50>MM200 ainda."
    },
    {
      "indicator": "EMA9",
      "reading": "9.0154",
      "interpretation": "EMA9 > EMA21 -> reversões de curto prazo favorecem compradores."
    },
    {
      "indicator": "EMA21",
      "reading": "8.9089",
      "interpretation": "Confirma suporte dinâmico de curto prazo (EMA9 acima dela)."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD=0.1320; sinal=0.1487; hist=-0.0167",
      "interpretation": "MACD positivo, mas abaixo da linha de sinal (histograma negativo) -> perda de momentum de curtíssimo prazo/risco de consolidação."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "BB_lower=8.7289; BB_mid=8.9865; BB_upper=9.2441",
      "interpretation": "Preço próximo à banda superior; bandas alargadas indicam volatilidade e viés altista, com risco de pullback para BB_mid."
    },
    {
      "indicator": "RSI14",
      "reading": "61.3161",
      "interpretation": "Acima de 50 e abaixo de 70 -> força compradora presente sem sobrecompra extrema."
    },
    {
      "indicator": "Volume",
      "reading": "9,162,930,600",
      "interpretation": "Volume relativamente elevado vs pregões recentes, conferindo confirmação parcial ao avanço do dia."
    }
  ]
}
